export function isReservedTenantSlug(raw: string): boolean {
  const s = raw.trim().toLowerCase();
  if (!s) return false;
  return RESERVED_TENANT_SLUG_STEMS.has(s);
}

/** Canonical OAuth / dogfood shell origin for a platform site zone. */
export function platformStudioPrimaryOrigin(siteBaseDomain: string): string {
  const base = siteBaseDomain
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, "")
    .replace(/\/$/, "");
  return `https://${PLATFORM_STUDIO_PRIMARY_SLUG}.${base}`;
}
